let cachedGraph = null;

export async function getDefaultCenter() {
  const [lat, lng] = OLIVOS_DATA.c;
  return { lat, lng };
}

export async function fetchStreets(_bboxIgnored) {
  if (cachedGraph) return cachedGraph;
  cachedGraph = buildGraphFromData(OLIVOS_DATA);
  return cachedGraph;
}

function buildGraphFromData(data) {
  const graph = { nodes: new Map(), ways: [], nodeList: [] };
  for (const [id, pos] of Object.entries(data.n || {})) {
    graph.nodes.set(String(id), { lat: pos[0], lng: pos[1], neighbors: new Map() });
  }
  for (const [a, b, dist] of data.e || []) {
    const idA = String(a), idB = String(b);
    const nodeA = graph.nodes.get(idA), nodeB = graph.nodes.get(idB);
    if (!nodeA || !nodeB) continue;
    nodeA.neighbors.set(idB, dist);
    nodeB.neighbors.set(idA, dist);
  }
  for (const [id, node] of graph.nodes) {
    if (node.neighbors.size > 0) graph.nodeList.push(id);
  }
  for (let i = 0; i < (data.w || []).length; i++) {
    graph.ways.push({ id: `w${i}`, coords: data.w[i] });
  }
  return graph;
}

function haversine(lat1, lng1, lat2, lng2) {
  const R = 6371000;
  const toRad = x => (x * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

export function findPath(graph, startId, goalId) {
  if (startId === goalId) return [startId];
  const open = new Map(), closed = new Set(), cameFrom = new Map();
  const startNode = graph.nodes.get(startId), goalNode = graph.nodes.get(goalId);
  if (!startNode || !goalNode) return null;
  open.set(startId, { g: 0, f: haversine(startNode.lat, startNode.lng, goalNode.lat, goalNode.lng) });
  cameFrom.set(startId, null);
  while (open.size > 0) {
    let currentId = null, bestF = Infinity;
    for (const [id, data] of open) { if (data.f < bestF) { bestF = data.f; currentId = id; } }
    if (currentId === goalId) {
      const path = []; let id = currentId;
      while (id !== null) { path.push(id); id = cameFrom.get(id); }
      return path.reverse();
    }
    const current = open.get(currentId);
    open.delete(currentId); closed.add(currentId);
    const node = graph.nodes.get(currentId);
    for (const [neighborId, dist] of node.neighbors) {
      if (closed.has(neighborId)) continue;
      const tentativeG = current.g + dist;
      const existing = open.get(neighborId);
      if (!existing || tentativeG < existing.g) {
        const neighbor = graph.nodes.get(neighborId);
        const h = haversine(neighbor.lat, neighbor.lng, goalNode.lat, goalNode.lng);
        open.set(neighborId, { g: tentativeG, f: tentativeG + h });
        cameFrom.set(neighborId, currentId);
      }
    }
  }
  return null;
}

export function nearestNode(graph, lat, lng) {
  if (!graph || !graph.nodeList || graph.nodeList.length === 0) return null;
  let bestId = null, bestDist = Infinity;
  for (const id of graph.nodeList) {
    const n = graph.nodes.get(id);
    const d = haversine(lat, lng, n.lat, n.lng);
    if (d < bestDist) { bestDist = d; bestId = id; }
  }
  return bestId;
}
